import{_ as a,a0 as s,w as e,s as l,ao as p,I as n,x as o,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"安卓編年史（30）：Android TV 和 Android Auto | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（30）：Android TV 和 Android Auto | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（30）：Android TV 和 Android Auto | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（30）：Android TV 和 Android Auto | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/30 - The (updated) history of Android","title":"安卓編年史（30）：Android TV 和 Android Auto","tag":"The history of Android","desc":""},"relativePath":"The history of Android/30 - The (updated) history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/30 - The (updated) history of Android.md"};function A(m,t,T,g,h,f){const d=s("Link");return e(),l("div",null,[t[22]||(t[22]=p('<h1 id="安卓編年史-30-android-tv-和-android-auto" tabindex="-1">安卓編年史（30）：Android TV 和 Android Auto <a class="header-anchor" href="#安卓編年史-30-android-tv-和-android-auto" aria-label="Permalink to “安卓編年史（30）：Android TV 和 Android Auto”">​</a></h1><h3 id="android-tv" tabindex="-1">Android TV <a class="header-anchor" href="#android-tv" aria-label="Permalink to “Android TV”">​</a></h3><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/IMG_0002-22-1440x545.jpg" alt=""></p><p>2014 年 11 月谷歌公佈了安卓 TV，安卓繼續進行它帶着一塊屏幕征服一切的征程。這家公司裏的一個部門之前在蜂巢時代嘗試過用谷歌 TV 掌控客廳，但這次完全是來自安卓團隊的新點子。安卓 TV 使用安卓 5.0 棒棒糖，並給了它一個為室內最大屏幕設計的 Material Design 界面。首發硬件谷歌選擇了華碩來代工“Nexus Player”，這是一個配置不足但夠用的機頂盒。</p><p>安卓 TV 專注於三樣東西：視頻，音樂，以及遊戲。你可以用一個小遙控器控制電視，它只有四向方向鍵以及四個按鈕，後退、主頁、麥克風以及播放/暫停。至於遊戲，華碩克隆了一個 Xbox 360 手柄，給了玩家一堆按鍵和一對搖桿。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2014/11/device-2014-10-31-172334.png" alt=""></p><p>安卓 TV 的界面很簡單。大幅的媒體略縮圖佔據了屏幕，可以橫向滾動，這些媒體中有 Youtube、Google Play、Netflix、Hulu 以及其它來源。這些略縮圖實際上是來自不同媒體源的“推薦”項目，它不是簡單地將一個應用的內容填滿屏幕。在那下面你可以直接訪問應用和設置。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2014/11/search-2.png" alt=""></p><p>語音界面很贊。你可以告訴安卓 TV 播放任意你想要的內容，而不用通過圖形界面去尋找。你還能在內容裏獲得更聰明的搜索結果，比如“顯示和 Harrison Ford 有關的電影”。每個應用都可以給索引服務提供內容，而不是簡單的應用集合。所有的這些應用都在 Play 商店有一個 TV 版本。開發者對安卓 TV 的特別支持還包括谷歌 cast 協議，允許用户從他們的手機和平板向電視投射視頻和音樂。</p><h3 id="android-5-1-lollipop" tabindex="-1">Android 5.1 Lollipop <a class="header-anchor" href="#android-5-1-lollipop" aria-label="Permalink to “Android 5.1 Lollipop”">​</a></h3>',10)),n("p",null,[t[1]||(t[1]=o("安卓 5.1 在 2015 年 3 月發佈，這是安卓最小的更新。它的目的主要是",-1)),r(d,{href:"http://arstechnica.com/gadgets/2015/03/a-look-at-android-5-1-speed-security-tweaks/"},{default:i(()=>[...t[0]||(t[0]=[o("修復 Nexus 6 上的加密性能問題",-1)])]),_:1}),t[2]||(t[2]=o("，還添加了設備保護和一些小的界面調整。",-1))]),t[23]||(t[23]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/lock1.jpg",alt:""})],-1)),t[24]||(t[24]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/2015-03-14-17.33.58.png",alt:""})],-1)),t[25]||(t[25]=n("p",null,"設備保護是唯一的新增界面，採用的是在開機設置顯示新警告的形式。這個特性在設備被偷了之後“保護你的設備不被再次利用”。一旦設置了鎖屏，設備保護就開始介入，並且會在擦除設備的時候被觸發。如果你以機主正常的方式擦除設備——解鎖手機並從設置選擇“重置”——什麼都不會發生。但如果你通過開發者工具擦除，設備會在下次開機設置的時候要求你“驗證之前同步的谷歌賬户”。",-1)),t[26]||(t[26]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/screen-pin-2.jpg",alt:""})],-1)),t[27]||(t[27]=n("p",null,[n("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2015/03/time-picker.jpg",alt:""})],-1)),n("p",null,[t[4]||(t[4]=o("這個想法是基於開發者是會知道之前登錄的谷歌帳號憑證的，但小偷就不知道了，他們會卡在設置這一步。在現實中這引發了",-1)),r(d,{href:"http://www.androidpolice.com/2016/08/11/rootjunky-discovers-frp-bypass-method-newer-samsung-phones/"},{default:i(()=>[...t[3]||(t[3]=[o("一個貓鼠遊戲",-1)])]),_:1}),t[5]||(t[5]=o("，人們尋找漏洞來繞過設備保護，而谷歌知道了這個 bug 並修補它。OEM 定製也引入了一些有趣的 bug 來繞過設備保護。",-1))]),t[28]||(t[28]=p('<p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/03/icons.jpg" alt=""></p><p>還有很多特別微小的界面改動，我們沒法一一列在上面的圖中。除了上面的圖片描述之外沒什麼可説的了。</p><h3 id="android-auto" tabindex="-1">Android Auto <a class="header-anchor" href="#android-auto" aria-label="Permalink to “Android Auto”">​</a></h3><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/Android_Auto_The_right_information_for_the_road_ahead_-_YouTube_-_Google_Chrome_2016-10-29_19-49-56-1440x810.jpg" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/Android-Auto-1440x882.jpg" alt=""></p><p>同樣是在 2015 年 3 月，谷歌發佈了“安卓 Auto”，一個基於安卓界面的全新車載娛樂信息系統。安卓 Auto 是谷歌面對蘋果的 CarPlay 交出的答卷，它們很多地方都很相似。安卓 Auto 不完全是個操作系統——它是一個運行在你手機上的“投射”界面，使用車載顯示屏作為一塊外置顯示器。運行安卓 Auto 意味着擁有一款兼容的汽車，在手機上（安卓 5.0 及以上版本）安裝了安卓 Auto 應用，並用 USB 線將手機連接到汽車。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-09-105548.png" alt=""></p><p>安卓 Auto 給你已有的車載系統帶來了谷歌的 Material Design 界面，給這個[通常掙扎於]設計好軟件的平台帶來了頂級的軟件設計。安卓 Auto 是個對安卓界面的完全重新設計，以遵循世界各地對車載系統無數的規定。它沒有通常充滿應用圖標的“主屏”，安卓的導航欄也變為了一個常駐的應用啓動器（幾乎像是個標籤頁式的界面）。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-10-113659.png" alt=""></p><p>算下來特性實際上只有四部分，導航欄從左到右是：谷歌地圖，一個撥號/聯繫人界面，“主屏”部分混合了 Google Now 和一個通知面板，還有一個音樂頁面。最後一個按鈕是一個“OEM”頁面，讓你可以退出安卓 Auto，返回到自帶的車載系統（這也是為了放置汽車製造商的定製特性）。安卓 Auto 還帶有谷歌的語音命令系統，以一個麥克風按鈕的形式顯示在屏幕右上角。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-09-091514.png" alt=""></p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2015/07/screendump-2015-07-09-110323.png" alt=""></p><p>安卓 Auto 的應用沒有多少。它只允許兩個類別的應用：音樂和信息應用。車載信息娛樂系統的規定意味着自定義界面不是個好選擇。信息應用沒有界面，並且可以接入語音系統，音樂應用也不會太多地改變界面，僅僅只是調整一下谷歌默認的“音樂應用”模板的顏色和圖標。但實際上重要的是音樂和消息的送達，在不讓駕駛員太多分心的情況下，一般的應用就沒法使用了。</p>',13)),n("p",null,[t[7]||(t[7]=o("安卓 Auto 在它的最初發布之後就沒看到多少更新了，但已經逐漸有很多汽車製造商支持了。到了 2017 年，將會有",-1)),r(d,{href:"http://www.usatoday.com/story/money/cars/2016/10/11/android-auto-comes-more-than-100-car-models-2017/91884366/"},{default:i(()=>[...t[6]||(t[6]=[o("超過 100",-1)])]),_:1}),t[8]||(t[8]=o(" 款支持的汽車型號。",-1))]),t[29]||(t[29]=n("hr",null,null,-1)),t[30]||(t[30]=n("p",null,"作者簡介：",-1)),t[31]||(t[31]=n("p",null,"Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),t[32]||(t[32]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),r(d,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/30/"},{default:i(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/30/",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=o("作者：",-1)),r(d,{href:"http://arstechnica.com/author/ronamadeo/"},{default:i(()=>[...t[11]||(t[11]=[o("RON AMADEO",-1)])]),_:1}),t[15]||(t[15]=o(" 譯者：",-1)),r(d,{href:"https://github.com/alim0x"},{default:i(()=>[...t[12]||(t[12]=[o("alim0x",-1)])]),_:1}),t[16]||(t[16]=o(" 校對：",-1)),r(d,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=o("本文由 ",-1)),r(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[17]||(t[17]=[o("LCTT",-1)])]),_:1}),t[20]||(t[20]=o(" 原創編譯，",-1)),r(d,{href:"https://linux.cn/"},{default:i(()=>[...t[18]||(t[18]=[o("Linux中國",-1)])]),_:1}),t[21]||(t[21]=o(" 榮譽推出",-1))])])}const y=a(u,[["render",A]]);export{V as __pageData,y as default};
